using System.Text.Json;using PlayerOne.Windows.Models;using PlayerOne.Windows.Services;namespace PlayerOne.Windows;
public partial class CatalogWindow:System.Windows.Window{readonly DeviceAuth auth;readonly string kind;readonly PlayerOneApi api=new();List<XtreamItem> all=[];string? host,user,pass;public CatalogWindow(DeviceAuth a,string k){InitializeComponent();auth=a;kind=k;TitleText.Text=k.ToUpperInvariant();Loaded+=async(_,__)=>await LoadAsync();}
async Task LoadAsync(){using var d=await api.GetPlaylistsAsync(auth);if(!d.RootElement.TryGetProperty("playlists",out var arr)||arr.GetArrayLength()==0)return;var selected=PlaylistSelectionStore.Load();JsonElement p=arr[0];foreach(var x in arr.EnumerateArray())if(selected==x.GetProperty("id").GetInt64()){p=x;break;}var id=p.GetProperty("id").GetInt64();PlaylistSelectionStore.Save(id);using var cfg=await api.GetPlaylistConfigAsync(auth,id);var q=cfg.RootElement.GetProperty("playlist");var type=q.TryGetProperty("type",out var t)?t.ToString().ToLowerInvariant():"";if(type=="xtream"){host=q.GetProperty("host").ToString();user=q.GetProperty("username").ToString();pass=q.GetProperty("password").ToString();all=await new XtreamClient().LoadAsync(host,user,pass,kind);Bind();}else if(type=="m3u"&&q.TryGetProperty("url",out var u)){all=await new M3uClient().LoadAsync(u.ToString(),kind);Bind();}}}
void Bind(){var gs=all.Select(x=>x.Group).Distinct().ToList();Groups.ItemsSource=new[]{"All"}.Concat(gs);Groups.SelectedIndex=0;Filter();}
void Filter(){var g=Groups.SelectedItem?.ToString();var s=SearchBox.Text.Trim();Items.ItemsSource=all.Where(x=>(g=="All"||string.IsNullOrEmpty(g)||x.Group==g)&&(s.Length==0||x.Name.Contains(s,StringComparison.OrdinalIgnoreCase))).ToList();}
void Group_Changed(object s,System.Windows.Controls.SelectionChangedEventArgs e)=>Filter();void Search_Changed(object s,System.Windows.Controls.TextChangedEventArgs e)=>Filter();
void Item_DoubleClick(object s,System.Windows.Input.MouseButtonEventArgs e){if(Items.SelectedItem is not XtreamItem x)return;if(kind=="series"&&x.StreamUrl is null&&host is not null&&user is not null&&pass is not null)new SeriesWindow(auth,x,host,user,pass).Show();else if(x.StreamUrl is not null)new PlayerWindow(auth,x).Show();}
}